def f(inp):
    h,w=len(inp),len(inp[0])
    out=[list(map(int,row)) for row in inp]
    # try: replace each cell by mode of its 8 neighbors; cells already majority stay
    th=(h+1)//2,tw=(w+1)//2
    for r in range(h):
        for c in range(w):
            nb=[]
            for dr in range(-th,1):
                for dc in range(-tw,1):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w:
                        nb.append(inp[rr][cc])
            mx=max(Counter(nb).most_common())
            if mx[1]!=nb.count(mx[0]):
                out[r][c]=mx[0]
    return out
