from collections import Counter
def components(g, val):
    h,w=len(g),len(g[0]); seen=set()
    comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==val and (r,c) not in seen:
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop(); key=(y,x)
                    if key in seen: continue
                    seen.add(key); comp.append(key)
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==val and (ny,nx) not in seen:
                            stack.append((ny,nx))
                comps.append(comp)
    return comps
