G=load(); print(sorted(G))

def solve(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]!=bg: stack.append((ny,nx))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                dom=Counter(g[p[0]][p[1]] for p in comp).most_common(1)[0][0]
                comps.append({'cells':comp,'bbox':(min(rs),max(rs),min(cs),max(cs)), 'dom':dom})
    out=[row[:] for row in g]
    for comp in comps:
        r0,r1,c0,c1=comp['bbox']
        for rr in range(r0,r1+1):
            for cc in range(c0,c1+1):
